import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        String s = sc.nextLine().trim();
        char[] chArr = s.toCharArray();

        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = sc.nextInt();
        }
        sc.nextLine();

        List<CharPair> mismatchChars = new ArrayList<>();
        List<CharPair> pairList = new ArrayList<>();
        for (int i = 0; i < n / 2; i++) {
            if (vals[i] > vals[n - i - 1]) {
                swapChars(chArr, vals, i);
            }
            CharPair cp = new CharPair(chArr[i], vals[i], i);
            if (chArr[i] == chArr[n - i - 1]) {
                mismatchChars.add(cp);
            }
            pairList.add(cp);
        }
        pairList.sort(Comparator.comparing(c -> c.value));

        int diffSum = 0;
        if (!isAntiPalindromic(chArr)) {
            if (mismatchChars.size() == 1) {
                CharPair wrong = mismatchChars.get(0);
                for (CharPair cp : pairList) {
                    if (cp.chr != wrong.chr && chArr[n - cp.idx - 1] != wrong.chr) {
                        diffSum = wrong.value + cp.value;
                        break;
                    }
                }
            } else if (mismatchChars.size() > 1) {
                Map<Character, Integer> countMap = new HashMap<>();
                for (CharPair cp : mismatchChars) {
                    countMap.put(cp.chr, countMap.getOrDefault(cp.chr, 0) + 1);
                }
                int maxCount = Collections.max(countMap.values());
                List<CharPair> appendList = new ArrayList<>();
                while (maxCount * 2 > mismatchChars.size() + appendList.size()) {
                    char maxChar = Collections.max(countMap.entrySet(), Map.Entry.comparingByValue()).getKey();
                    for (CharPair cp : pairList) {
                        if (cp.chr != maxChar && chArr[n - cp.idx - 1] != maxChar && !mismatchChars.contains(cp) && !appendList.contains(cp)) {
                            appendList.add(cp);
                            break;
                        }
                    }
                }
                diffSum = mismatchChars.stream().mapToInt(c -> c.value).sum() + appendList.stream().mapToInt(c -> c.value).sum();
            }
        }
        int totalSum = Arrays.stream(vals).sum();
        System.out.println(totalSum - diffSum);
    }

    private static void swapChars(char[] chArr, int[] vals, int i) {
        char temp = chArr[i];
        chArr[i] = chArr[chArr.length - i - 1];
        chArr[chArr.length - i - 1] = temp;

        int tempVal = vals[i];
        vals[i] = vals[vals.length - i - 1];
        vals[vals.length - i - 1] = tempVal;
    }

    private static boolean isAntiPalindromic(char[] chArr) {
        int len = chArr.length;
        for (int i = 0; i < len / 2; i++) {
            if (chArr[i] == chArr[len - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class CharPair {
        char chr;
        int value;
        int idx;

        CharPair(char chr, int value, int idx) {
            this.chr = chr;
            this.value = value;
            this.idx = idx;
        }
    }
}
