class CharPair:
    def __init__(self, chr, value, idx):
        self.chr = chr
        self.value = value
        self.idx = idx

def swapChars(chArr, vals, i):
    chArr[i], chArr[len(chArr) - i - 1] = chArr[len(chArr) - i - 1], chArr[i]
    vals[i], vals[len(vals) - i - 1] = vals[len(vals) - i - 1], vals[i]

def isAntiPalindromic(chArr):
    length = len(chArr)
    for i in range(length // 2):
        if chArr[i] == chArr[length - i - 1]:
            return False
    return True

mismatchChars = []
pairList = []

for i in range(n // 2):
    if vals[i] > vals[n - i - 1]:
        swapChars(chArr, vals, i)
    cp = CharPair(chArr[i], vals[i], i)
    if chArr[i] == chArr[n - i - 1]:
        mismatchChars.append(cp)
    pairList.append(cp)

pairList.sort(key=lambda c: c.value)

diffSum = 0
if not isAntiPalindromic(chArr):
    if len(mismatchChars) == 1:
        wrong = mismatchChars[0]
        for cp in pairList:
